import express from 'express';
import { SQL } from 'bun';
import { requirePatientAuth } from '../middleware/patient.js';

const app = express();
const sql = new SQL(process.env.DATABASE_URL);

app.get('/api/clinical/lab-reports/:reportId', requirePatientAuth, async (req, res) => {
  const { reportId } = req.params;

  // Constrain SQL query strictly to the authenticated patient's ID
  const reports = await sql`
    SELECT id, patient_id, test_category, biomarker_results, status, physician_notes
    FROM clinical_lab_reports
    WHERE id = ${reportId} AND patient_id = ${req.patient.id}
  `;

  if (reports.length === 0) {
    return res.status(404).json({ error: 'Lab report not found or access denied' });
  }

  const report = reports[0];
  res.json({ report });
});

export default app;
